import React, { useState, useEffect } from 'react';
import { Grid, GridColumn } from '@progress/kendo-react-grid';
import { searchTracks, getTrackDetails } from '../services/api';

const TrackSearch = ({ searchTerm }) => {
  const [filteredTracks, setFilteredTracks] = useState([]);
  const [trackDetails, setTrackDetails] = useState({});

  useEffect(() => {
    if (searchTerm) {
      searchTracks(searchTerm).then(async tracks => {
        setFilteredTracks(tracks);

        const detailsPromises = tracks.map(track =>
          getTrackDetails(track.id).then(details => ({ [track.id]: details }))
        );
        const detailsArray = await Promise.all(detailsPromises);
        setTrackDetails(Object.assign({}, ...detailsArray));
      }).catch(error => console.error('Error fetching tracks:', error));
    }
  }, [searchTerm]);

  // Merge details into track data
  const enrichedTracks = filteredTracks.map(track => ({
    ...track,
    ...trackDetails[track.id],
  }));

  return (
    <div style={{ width: '100%', marginTop: '20px' }}>
      <Grid
        data={enrichedTracks}
        style={{ height: '500px', width: '100%' }}
        sortable
        filterable
        resizable
      >
        <GridColumn field="name" title="Track Name" width="150px" />
        <GridColumn field="artists[0].name" title="Artist Name" width="150px" 
          cell={props => <td>{props.dataItem.artists?.[0]?.name || 'Unknown'}</td>} 
        />
        <GridColumn field="album.name" title="Album Name" width="150px" />
        <GridColumn field="album.release_date" title="Release Date" width="100px" 
          cell={props => <td>{props.dataItem.album?.release_date?.split('-')[0] || 'Unknown'}</td>} 
        />
        <GridColumn field="tempo" title="Tempo" width="100px" />
        <GridColumn field="key" title="Key" width="100px" />
        <GridColumn field="danceability" title="Danceability" width="100px" />
        <GridColumn field="energy" title="Energy" width="100px" />
        <GridColumn field="valence" title="Valence" width="100px" />
        <GridColumn field="acousticness" title="Acousticness" width="100px" />
        <GridColumn field="instrumentalness" title="Instrumentalness" width="100px" />
        <GridColumn field="liveness" title="Liveness" width="100px" />
        <GridColumn field="genres" title="Genre" width="150px" 
          cell={props => <td>{props.dataItem.genres?.join(', ') || ''}</td>}
        />
        <GridColumn 
          field="id" 
          title="Preview" 
          width="250px"
          cell={props => (
            <td>
              <iframe
                src={`https://open.spotify.com/embed/track/${props.dataItem.id}`}
                width="100%"
                height="80"
                allow="encrypted-media"
                frameBorder="0"
                style={{ border: 'none' }}
                title={`Spotify preview of ${props.dataItem.name}`}
              ></iframe>
            </td>
          )}
        />
      </Grid>
    </div>
  );
};

export default TrackSearch;
